const pick = (el) => { const s = getComputedStyle(el); return {tag: el.tagName, text: (el.innerText||'').slice(0,40), font: s.fontFamily, size: s.fontSize, weight: s.fontWeight, lh: s.lineHeight, ls: s.letterSpacing, color: s.color, bg: s.backgroundColor, radius: s.borderRadius, tt: s.textTransform}; };
const sel = ['body','h1','h2','h3','h4','p','a','button','nav a','footer'];
const out = {};
for (const q of sel) { const els = [...document.querySelectorAll(q)].filter(e=>e.offsetParent!==null).slice(0,3); out[q] = els.map(pick); }
const colors = {}, bgs = {}, fonts = {}, radii = {}, borders = {};
for (const el of document.querySelectorAll('body *')) { if (el.offsetParent===null) continue; const s = getComputedStyle(el); colors[s.color]=(colors[s.color]||0)+1; if (s.backgroundColor!=='rgba(0, 0, 0, 0)') bgs[s.backgroundColor]=(bgs[s.backgroundColor]||0)+1; fonts[s.fontFamily]=(fonts[s.fontFamily]||0)+1; if (s.borderRadius!=='0px') radii[s.borderRadius]=(radii[s.borderRadius]||0)+1; if (s.borderTopWidth!=='0px') borders[s.borderTopWidth+' '+s.borderTopColor]=(borders[s.borderTopWidth+' '+s.borderTopColor]||0)+1; }
const top = o => Object.entries(o).sort((a,b)=>b[1]-a[1]).slice(0,12);
const vars = {}; for (const sh of document.styleSheets) { try { for (const r of sh.cssRules) { if (r.selectorText===':root' || r.selectorText==='html') { for (const p of r.style) if (p.startsWith('--')) vars[p]=r.style.getPropertyValue(p).trim(); } } } catch(e){} }
const fontFaces = [...document.fonts].map(f=>f.family+' '+f.weight+' '+f.status).filter((v,i,a)=>a.indexOf(v)===i);
const links = [...document.querySelectorAll('link[rel=stylesheet],link[href*=font]')].map(l=>l.href);
JSON.stringify({out, colors: top(colors), bgs: top(bgs), fonts: top(fonts), radii: top(radii), borders: top(borders), vars: Object.entries(vars).slice(0,80), fontFaces, links}, null, 1)

