{%- macro aircraft_url(tail) -%}
/?{% if query %}q={{ query | urlencode }}&amp;{% endif %}aircraft={{ tail }}#row-{{ tail }}
{%- endmacro -%}

{%- macro kept(form_id, field, default="") -%}
{{ failure.values.get(field, default) if failure and failure.form_id == form_id else default }}
{%- endmacro -%}

{%- macro error_for(form_id) -%}
{% if failure and failure.form_id == form_id %}<p class="error" role="alert">{{ failure.message }}</p>{% endif %}
{%- endmacro -%}

{%- macro action(writeup, name, label, button) -%}
{% set form_id = writeup.id ~ "-" ~ name %}
<details class="action"{% if failure and failure.form_id == form_id %} open{% endif %}>
  <summary>{{ label }}</summary>
  <form method="post" action="/writeups/{{ writeup.id }}/{{ name }}">
    {{ error_for(form_id) }}
    {{ caller(form_id) }}
    <label class="field">
      <span>Your name</span>
      <input name="actor" required autocomplete="name" value="{{ kept(form_id, 'actor') }}">
    </label>
    <button class="button">{{ button }}</button>
  </form>
</details>
{%- endmacro -%}

{%- macro date_field(form_id, current) -%}
<label class="field">
  <span>Finish by</span>
  <input type="date" name="scheduled_date" required min="{{ today.isoformat() }}"
    value="{{ kept(form_id, 'scheduled_date', current.isoformat() if current else '') }}">
</label>
{%- endmacro -%}

{%- macro note_field(form_id, label) -%}
<label class="field">
  <span>{{ label }}</span>
  <textarea name="note" rows="2" required>{{ kept(form_id, 'note') }}</textarea>
</label>
{%- endmacro -%}

{%- macro event_text(entry) -%}
{% set event = entry.event %}
{% if event is none %}Filed as {{ entry.writeup.severity }}
{% elif event.kind == "scheduled" %}Scheduled to finish by {{ event.to_value | day }}
