          {% if writeup.status == "scheduled" or writeup.status == "in_progress" %}{% if writeup.scheduled_date < today %}<span class="flag">Overdue</span>{% endif %}{% endif %}
          {% if writeup.status == "unscheduled" %}<span class="flag">Needs scheduling</span>{% endif %}
        </header>
        <p class="description">{{ writeup.description }}</p>
        <p class="meta">#{{ writeup.id }} · reported by {{ writeup.reported_by }}, {{ writeup.reported_at | local_time(now) }}</p>

