          {% if writeup.status == "unscheduled" %}
            {% call(form_id) action(writeup, "schedule", "Schedule", "Schedule repair") %}{{ date_field(form_id, none) }}{% endcall %}
          {% elif writeup.status == "scheduled" %}
            {% call(form_id) action(writeup, "start", "Start work", "Start work") %}{% endcall %}
            {% call(form_id) action(writeup, "schedule", "Reschedule", "Reschedule") %}{{ date_field(form_id, writeup.scheduled_date) }}{% endcall %}
            {% call(form_id) action(writeup, "unschedule", "Unschedule", "Unschedule") %}{% endcall %}
          {% else %}
            {% call(form_id) action(writeup, "resolve", "Resolve", "Resolve write-up") %}{{ note_field(form_id, "What was done") }}{% endcall %}
            {% call(form_id) action(writeup, "schedule", "Reschedule", "Reschedule") %}{{ date_field(form_id, writeup.scheduled_date) }}{% endcall %}
          {% endif %}
          {% call(form_id) action(writeup, "severity", "Change severity", "Change severity") %}
            <label class="field">
              <span>New severity</span>
              <select name="severity" required>
                <option value="">Choose</option>
                {% for severity in ["high", "medium", "low"] if severity != writeup.severity %}
                <option value="{{ severity }}"{% if kept(form_id, 'severity') == severity %} selected{% endif %}>{{ severity | capitalize }}</option>
                {% endfor %}
              </select>
            </label>
            {{ note_field(form_id, "Reason") }}
          {% endcall %}
          {% call(form_id) action(writeup, "description", "Edit description", "Save description") %}
            <label class="field">
              <span>Description</span>
              <textarea name="description" rows="3" required>{{ kept(form_id, 'description', writeup.description) }}</textarea>
            </label>
          {% endcall %}
          {% call(form_id) action(writeup, "cancel", "Cancel write-up", "Cancel write-up") %}{{ note_field(form_id, "Reason") }}{% endcall %}
        </div>
      </article>
      {% else %}
      <p class="empty">No open write-ups.</p>
      {% endfor %}
    </section>

    <section class="history" aria-labelledby="history-title">
      <h3 id="history-title">History</h3>
      <ol class="timeline">
        {% for entry in timeline %}
        <li>
          <p class="when"><time>{{ entry.at | local_time(now) }}</time> · {{ entry.actor }}</p>
          <p class="what">{{ event_text(entry) }}</p>
          {% if entry.event and entry.event.note %}<p class="note">{{ entry.event.note }}</p>{% endif %}
          <p class="ref"><a href="#writeup-{{ entry.writeup.id }}">#{{ entry.writeup.id }}</a> {{ entry.writeup.description }}</p>
        </li>
        {% else %}
        <li class="empty">Nothing has been filed against this aircraft.</li>
        {% endfor %}
      </ol>
    </section>
  </aside>
  {% endif %}

</div>
</body>
</html>

