        <tr><th scope="col">Aircraft</th><th scope="col">Status</th><th scope="col" class="num">Open</th><th scope="col">Attention</th></tr>
      </thead>
      {% if query and not board.grounded and not board.cleared %}
      <tbody><tr><td colspan="4" class="empty">No aircraft match “{{ query }}”.</td></tr></tbody>
      {% else %}
      {% for key, label, rows in [("grounded", "Grounded", board.grounded), ("cleared", "Cleared", board.cleared)] %}
      <tbody class="group group-{{ key }}">
        <tr class="group-head"><th colspan="4" scope="colgroup">{{ label }} <span>{{ rows | length }}</span></th></tr>
        {% for row in rows %}
        {% set tail = row.aircraft.tail_number %}
        <tr id="row-{{ tail }}"{% if aircraft and aircraft.id == row.aircraft.id %} aria-current="true"{% endif %}>
          <th scope="row" class="tail"><a href="{{ aircraft_url(tail) }}">{{ tail }}</a></th>
          <td>
            {% if row.cleared %}
            <span class="status status-cleared">Cleared</span>
            {% else %}
            <span class="status status-grounded">Grounded</span>
            <ul class="reasons">
              {% for writeup in row.grounding %}<li>High: {{ writeup.description }}</li>{% endfor %}
            </ul>
            {% endif %}
          </td>
          <td class="num">{{ row.open_writeups | length or "None" }}</td>
          <td class="attention">
            {% if row.is_overdue(today) %}<span class="flag">Overdue</span>{% endif %}
            {% if row.needs_scheduling %}<span class="flag">Needs scheduling</span>{% endif %}
          </td>
        </tr>
        {% else %}
        <tr><td colspan="4" class="empty">{% if query %}No {{ key }} aircraft match “{{ query }}”.{% else %}No aircraft {{ key }}.{% endif %}</td></tr>
        {% endfor %}
      </tbody>
      {% endfor %}
      {% endif %}
    </table>
  </main>

  {% if aircraft %}
  <aside class="panel" aria-labelledby="panel-title">
    <a class="panel-close" href="/{% if query %}?q={{ query | urlencode }}{% endif %}#row-{{ aircraft.tail_number }}">
      <span class="wide-only">Close</span><span class="narrow-only">Back to fleet</span>
    </a>

    <header class="panel-head">
      <h2 id="panel-title">{{ aircraft.tail_number }}</h2>
      {% if status.cleared %}
      <p class="status status-cleared">Cleared to fly</p>
      <p class="panel-reason">No open High write-ups.</p>
      {% else %}
      <p class="status status-grounded">Grounded</p>
      <p class="panel-reason">{{ status.grounding | length }} open High write-up{{ "s" if status.grounding | length > 1 }} must be resolved or canceled.</p>
      {% endif %}
    </header>

    <details class="file-writeup"{% if failure and failure.form_id == "file" %} open{% endif %}>
      <summary class="button">Create write-up</summary>
      <form method="post" action="/aircraft/{{ aircraft.id }}/writeups">
        {{ error_for("file") }}
        <fieldset class="field">
          <legend>Severity</legend>
          <div class="choices">
            {% for severity in ["high", "medium", "low"] %}
            <label><input type="radio" name="severity" value="{{ severity }}" required{% if kept('file', 'severity') == severity %} checked{% endif %}> {{ severity | capitalize }}</label>
            {% endfor %}
          </div>
        </fieldset>
        <label class="field">
          <span>What's wrong</span>
          <textarea name="description" rows="3" required>{{ kept("file", "description") }}</textarea>
        </label>
        <label class="field">
          <span>Your name</span>
          <input name="reported_by" required autocomplete="name" value="{{ kept('file', 'reported_by') }}">
        </label>
        <button class="button">File write-up</button>
      </form>
    </details>

    <section class="open-writeups" aria-labelledby="open-title">
      <h3 id="open-title">Open write-ups <span>{{ status.open_writeups | length }}</span></h3>
      {% for writeup in status.open_writeups %}
      <article class="writeup severity-{{ writeup.severity }}" id="writeup-{{ writeup.id }}">
        <header class="writeup-head">
          <span class="severity">{{ writeup.severity }}</span>
          <span class="writeup-status">{{ STATUS_LABELS[writeup.status] }}</span>
          {% if writeup.scheduled_date %}<span>Finish by {{ writeup.scheduled_date | day }}</span>{% endif %}
          {% if writeup.status == "scheduled" or writeup.status == "in_progress" %}{% if writeup.scheduled_date < today %}<span class="flag">Overdue</span>{% endif %}{% endif %}
          {% if writeup.status == "unscheduled" %}<span class="flag">Needs scheduling</span>{% endif %}
        </header>
        <p class="description">{{ writeup.description }}</p>
        <p class="meta">#{{ writeup.id }} · reported by {{ writeup.reported_by }}, {{ writeup.reported_at | local_time(now) }}</p>

        <div class="actions">
          {% if writeup.status == "unscheduled" %}
            {% call(form_id) action(writeup, "schedule", "Schedule", "Schedule repair") %}{{ date_field(form_id, none) }}{% endcall %}
          {% elif writeup.status == "scheduled" %}
            {% call(form_id) action(writeup, "start", "Start work", "Start work") %}{% endcall %}
            {% call(form_id) action(writeup, "schedule", "Reschedule", "Reschedule") %}{{ date_field(form_id, writeup.scheduled_date) }}{% endcall %}
            {% call(form_id) action(writeup, "unschedule", "Unschedule", "Unschedule") %}{% endcall %}
          {% else %}
            {% call(form_id) action(writeup, "resolve", "Resolve", "Resolve write-up") %}{{ note_field(form_id, "What was done") }}{% endcall %}
            {% call(form_id) action(writeup, "schedule", "Reschedule", "Reschedule") %}{{ date_field(form_id, writeup.scheduled_date) }}{% endcall %}
          {% endif %}
          {% call(form_id) action(writeup, "severity", "Change severity", "Change severity") %}
            <label class="field">
              <span>New severity</span>
              <select name="severity" required>
                <option value="">Choose</option>
                {% for severity in ["high", "medium", "low"] if severity != writeup.severity %}
                <option value="{{ severity }}"{% if kept(form_id, 'severity') == severity %} selected{% endif %}>{{ severity | capitalize }}</option>
                {% endfor %}
              </select>
            </label>
            {{ note_field(form_id, "Reason") }}
          {% endcall %}
          {% call(form_id) action(writeup, "description", "Edit description", "Save description") %}
            <label class="field">
              <span>Description</span>
              <textarea name="description" rows="3" required>{{ kept(form_id, 'description', writeup.description) }}</textarea>
            </label>
          {% endcall %}
          {% call(form_id) action(writeup, "cancel", "Cancel write-up", "Cancel write-up") %}{{ note_field(form_id, "Reason") }}{% endcall %}
        </div>
      </article>
      {% else %}
      <p class="empty">No open write-ups.</p>
      {% endfor %}
    </section>

    <section class="history" aria-labelledby="history-title">
      <h3 id="history-title">History</h3>
      <ol class="timeline">
        {% for entry in timeline %}
        <li>
          <p class="when"><time>{{ entry.at | local_time(now) }}</time> · {{ entry.actor }}</p>
          <p class="what">{{ event_text(entry) }}</p>
          {% if entry.event and entry.event.note %}<p class="note">{{ entry.event.note }}</p>{% endif %}
          <p class="ref"><a href="#writeup-{{ entry.writeup.id }}">#{{ entry.writeup.id }}</a> {{ entry.writeup.description }}</p>
        </li>
        {% else %}
        <li class="empty">Nothing has been filed against this aircraft.</li>
        {% endfor %}
      </ol>
    </section>
  </aside>
  {% endif %}

</div>
</body>
</html>

