const parse = c => { const m = c.match(/[\d.]+/g).map(Number); return {r:m[0],g:m[1],b:m[2],a:m[3]??1}; };
const lum = ({r,g,b}) => { const f = v => { v/=255; return v<=0.03928? v/12.92 : ((v+0.055)/1.055)**2.4; }; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const blend = (top, bot) => ({r: top.r*top.a + bot.r*(1-top.a), g: top.g*top.a + bot.g*(1-top.a), b: top.b*top.a + bot.b*(1-top.a), a:1});
const bgOf = el => { const layers=[]; for (let e=el; e; e=e.parentElement) { const c=parse(getComputedStyle(e).backgroundColor); if (c.a>0) layers.push(c); if (c.a===1) break; } let acc = {r:3,g:3,b:3,a:1}; for (const l of layers.reverse()) acc = blend(l, acc); return acc; };
const results = {};
for (const el of document.querySelectorAll('body *')) {
  if (!el.offsetParent) continue;
  const own = [...el.childNodes].some(n => n.nodeType===3 && n.textContent.trim());
  if (!own) continue;
  const s = getComputedStyle(el); const fg = blend(parse(s.color), bgOf(el)); const bg = bgOf(el);
  const [a,b] = [lum(fg), lum(bg)].sort((x,y)=>y-x); const ratio = (a+0.05)/(b+0.05);
  const key = s.color + ' on ' + `rgb(${Math.round(bg.r)},${Math.round(bg.g)},${Math.round(bg.b)})`;
  results[key] = Math.min(results[key] ?? 99, +ratio.toFixed(2));
}
Object.entries(results).sort((x,y)=>x[1]-y[1]).slice(0,10)

