</head>
<body{% if aircraft %} class="has-panel"{% endif %}>
<div class="layout">

  <main class="board">
    <header class="board-head">
      <h1>Fleet clearance</h1>
      <p class="summary">
        <span class="grounded">{{ board.grounded_count }} grounded</span>
        <span class="cleared">{{ board.fleet_size - board.grounded_count }} cleared</span>
        <span>{{ board.fleet_size }} aircraft</span>
