/* Tokens from tagup.ai's dark theme. Orange means caution only (DECISIONS.md 31). */
:root {
  color-scheme: dark;
  --bg: #030303;
  --surface: #0a0e1a;
  --raised: #111729;
  --fg: #f4f7ff;
  --muted: #a9b3c9;
  --border: #242b40;
  --grounded: #fca5a5;
  --grounded-tint: rgb(252 165 165 / 0.07);
  --cleared: #7cff6b;
  --caution: #ff4f00;
  --caution-text: #ff7a3d;

  --font-sans: "Barlow", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --gutter: clamp(1rem, 3vw, 2rem);
}

*, *::before, *::after { box-sizing: border-box; }

html { scrollbar-color: var(--border) var(--bg); }

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 400 15px/1.45 var(--font-sans);
  caret-color: var(--fg);
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--fg); color: var(--bg); }

:focus-visible { outline: 2px solid var(--fg); outline-offset: 2px; }

a { color: inherit; text-underline-offset: 0.2em; text-decoration-color: var(--muted); }
a:hover { text-decoration-color: var(--fg); }

h1, h2, h3, p, ul, ol { margin: 0; }

summary { cursor: pointer; list-style: none; }
summary::-webkit-details-marker { display: none; }

/* Labels and data in mono, as on tagup.ai. */
.fleet thead th, .group-head, .status, .flag, .severity, .state, .date,
.summary, .search label, .field > span, .field legend, .panel-close, .button,
.history h3, .open-writeups h3, .when {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* ---------- Layout ---------- */

.layout { min-height: 100vh; }

.board {
  padding: var(--gutter);
  max-width: 72rem;
}

@media (min-width: 960px) {
  .has-panel .layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(24rem, 30rem);
  }
  .panel {
    position: sticky;
    top: 0;
    height: 100vh;
    overflow-y: auto;
    border-left: 1px solid var(--border);
  }
  .narrow-only { display: none; }
}

@media (max-width: 959.98px) {
  .has-panel .board { display: none; }
  .wide-only { display: none; }
}

/* ---------- Board ---------- */

.board-head { display: grid; gap: 0.5rem; margin-bottom: 1.5rem; }

h1 { font-size: 28px; font-weight: 500; letter-spacing: -0.01em; line-height: 1.1; }

.summary { display: flex; flex-wrap: wrap; gap: 0.25rem 1.25rem; font-size: 13px; }
.summary .grounded { color: var(--grounded); }
.summary .cleared { color: var(--cleared); }

.as-of { color: var(--muted); font-size: 14px; }

.search {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.75rem;
  margin-bottom: 1.5rem;
}
.search label { color: var(--muted); }
.search input { width: 12rem; font-family: var(--font-mono); text-transform: uppercase; }
.search a { color: var(--muted); font-size: 14px; }

input, textarea, select {
  font: inherit;
  color: var(--fg);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 0;
  padding: 0.45rem 0.6rem;
}
input:hover, textarea:hover, select:hover { border-color: var(--muted); }
textarea { resize: vertical; width: 100%; }

.fleet { width: 100%; border-collapse: collapse; }

.fleet th, .fleet td {
  padding: 0.6rem 0.75rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--border);
}

.fleet thead th { color: var(--muted); padding-block: 0.5rem; }

.group-head > * { padding-top: 1.75rem; border-bottom-color: currentColor; }
.group-head span { margin-left: 0.5rem; }
.group-grounded .group-head { color: var(--grounded); }
.group-cleared .group-head { color: var(--cleared); }
.group-head .toggle { text-align: right; }
.toggle a { color: var(--muted); text-decoration: none; }
.toggle a:hover { color: var(--fg); }

.group-grounded tr:not(.group-head) { background: var(--grounded-tint); }

.fleet tbody tr:not(.group-head) { position: relative; }
.fleet tbody tr:not(.group-head):hover { background: var(--raised); }
.fleet tbody tr[aria-current="true"] { background: var(--raised); box-shadow: inset 0 0 0 1px var(--muted); }

.tail { width: 7rem; white-space: nowrap; }
.tail a {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
}
/* The whole row opens the aircraft. */
.tail a::after { content: ""; position: absolute; inset: 0; }
.tail a:focus-visible { outline: none; }
.tail a:focus-visible::after { outline: 2px solid var(--fg); outline-offset: -2px; }

.status-grounded { color: var(--grounded); }
.status-cleared { color: var(--cleared); }

/* A fixed severity column, so a wrapped description never reads as a second write-up. */
.row-writeups { list-style: none; padding: 0; margin-top: 0.35rem; display: grid; gap: 0.3rem; }
.row-writeups li { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr); gap: 0.5rem; max-width: 56ch; }
.row-writeups .severity { padding-top: 0.15em; }
.no-writeups { color: var(--muted); font-size: 14px; margin-top: 0.2rem; }

.severity { font-size: 11px; color: var(--muted); }
.severity-high { color: var(--grounded); }
.severity-medium { color: var(--fg); }

.attention { width: 12rem; }
.flags { display: flex; flex-wrap: wrap; gap: 0.35rem; }

.flag {
  display: inline-block;
  color: var(--caution-text);
  border: 1px solid var(--caution);
  padding: 0.1rem 0.4rem;
  font-size: 11px;
  white-space: nowrap;
}

.empty { color: var(--muted); }

/* ---------- Buttons ---------- */

/* Tagup's bracketed corners. */
.button {
  --corner: var(--fg);
  display: inline-block;
  cursor: pointer;
  color: var(--fg);
  border: 0;
  padding: 0.6rem 1rem;
  background:
    linear-gradient(var(--corner), var(--corner)) top left / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) top left / 1.5px 8px,
    linear-gradient(var(--corner), var(--corner)) top right / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) top right / 1.5px 8px,
    linear-gradient(var(--corner), var(--corner)) bottom left / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) bottom left / 1.5px 8px,
    linear-gradient(var(--corner), var(--corner)) bottom right / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) bottom right / 1.5px 8px,
    var(--raised);
  background-repeat: no-repeat;
}
.button:hover { background-color: var(--border); }

.link-button {
  font: inherit;
  font-size: 14px;
  color: var(--muted);
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
.link-button:hover { color: var(--fg); }

/* ---------- Aircraft panel ---------- */

.panel {
  background: var(--surface);
  padding: var(--gutter);
  display: grid;
  align-content: start;
  gap: 1.75rem;
}

.panel-close { color: var(--muted); text-decoration: none; justify-self: start; }
.panel-close:hover { color: var(--fg); }

.panel-head { display: grid; gap: 0.35rem; }
.panel-head h2 { font-family: var(--font-mono); font-size: 26px; font-weight: 500; letter-spacing: 0.02em; }
.panel-head .status { font-size: 14px; }
.panel-reason { color: var(--muted); }

.file-writeup[open] > summary { margin-bottom: 1rem; }

form { display: grid; gap: 0.9rem; }
form .button { justify-self: start; }
.form-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem; }

.field { display: grid; gap: 0.35rem; border: 0; padding: 0; margin: 0; }
.field > span, .field legend { color: var(--muted); padding: 0; margin-bottom: 0.35rem; }
.field input:not([type="radio"]), .field select { width: 100%; }
.choices { display: flex; gap: 1.25rem; }
.choices label { display: flex; align-items: center; gap: 0.4rem; cursor: pointer; }
input[type="radio"] { accent-color: var(--fg); margin: 0; }

.error {
  color: var(--grounded);
  border: 1px solid var(--grounded);
  background: var(--grounded-tint);
  padding: 0.5rem 0.75rem;
}

.open-writeups, .history { display: grid; gap: 0.75rem; }
.open-writeups h3 span { margin-left: 0.5rem; }
.open-writeups h3, .history h3 { color: var(--muted); }

/* ---------- Write-up cards: each part edits itself ---------- */

.writeup {
  border: 1px solid var(--border);
  background: var(--bg);
  padding: 0.9rem 1rem 1rem;
  display: grid;
  gap: 0.6rem;
  scroll-margin-top: 1rem;
}
.writeup.severity-high { border-color: rgb(252 165 165 / 0.45); }

.card-top { display: flex; align-items: center; gap: 0.6rem; min-height: 1.75rem; }
.corner { margin-left: auto; display: flex; align-items: center; gap: 0.5rem; }

.state {
  font-size: 11px;
  color: var(--muted);
  border: 1px solid var(--border);
  background: var(--raised);
  padding: 0.1rem 0.45rem;
}

.edit { position: relative; }

/* Severity and date look like what they are, with a dotted underline to say they can change. */
.edit-severity > summary, .edit-date > summary {
  padding: 0.15rem 0.25rem;
  margin: -0.15rem -0.25rem;
  text-decoration: underline dotted;
  text-decoration-color: var(--border);
  text-underline-offset: 0.35em;
}
.edit-severity > summary:hover, .edit-date > summary:hover,
.edit-severity[open] > summary, .edit-date[open] > summary {
  background: var(--raised);
  text-decoration-color: currentColor;
}
.edit-date > summary { color: var(--fg); font-size: 12px; }

.popover {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: 0;
  z-index: 5;
  width: min(20rem, calc(100vw - 4rem));
  background: var(--raised);
  border: 1px solid var(--border);
  padding: 1rem;
  box-shadow: 0 12px 32px rgb(0 0 0 / 0.6);
  text-transform: none;
  letter-spacing: normal;
}
.popover-end { left: auto; right: 0; }

.edit-description > summary {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  font-size: 16px;
  padding: 0.25rem 0.4rem;
  margin: -0.25rem -0.4rem;
}
.edit-description > summary::after {
  content: "Edit";
  flex: none;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: 0;
}
.edit-description > summary:hover { background: var(--raised); }
.edit-description > summary:hover::after,
.edit-description > summary:focus-visible::after { opacity: 1; }
.edit-description[open] > summary { color: var(--muted); }
.edit-description[open] > summary::after { content: "Close"; opacity: 1; }
.edit-description[open] > form { margin-top: 0.75rem; }
@media (hover: none) {
  .edit-description > summary::after { opacity: 1; }
}

.meta { color: var(--muted); font-size: 13px; }

.card-actions {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  border-top: 1px solid var(--border);
  padding-top: 0.9rem;
  margin-top: 0.15rem;
}
.edit-step { flex: 1; }
.edit-step[open] > summary { background-color: var(--border); }
.edit-step[open] > form { margin-top: 1rem; }
