  --muted: #a9b3c9;
  --border: #242b40;
  --grounded: #fca5a5;
  --grounded-tint: rgb(252 165 165 / 0.07);
  --cleared: #7cff6b;
  --caution: #ff4f00;
  --caution-text: #ff7a3d;

  --font-sans: "Barlow", ui-sans-serif, system-ui, sans-serif;
