.row-writeups li { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr); gap: 0.5rem; max-width: 56ch; }
.row-writeups .severity { padding-top: 0.15em; }
.no-writeups { color: var(--muted); font-size: 14px; margin-top: 0.2rem; }

.severity { font-size: 11px; color: var(--muted); }
.severity-high { color: var(--grounded); }
.severity-medium { color: var(--fg); }

