.row-writeups li { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr); gap: 0.5rem; max-width: 56ch; }
.row-writeups .severity { padding-top: 0.15em; }
.no-writeups { color: var(--muted); font-size: 14px; margin-top: 0.2rem; }

.severity { font-size: 11px; color: var(--muted); }
.severity-high { color: var(--grounded); }
.severity-medium { color: var(--fg); }

.attention { width: 12rem; }
.flags { display: flex; flex-wrap: wrap; gap: 0.35rem; }

.flag {
  display: inline-block;
  color: var(--caution-text);
  border: 1px solid var(--caution);
  padding: 0.1rem 0.4rem;
  font-size: 11px;
  white-space: nowrap;
}

.empty { color: var(--muted); }

/* ---------- Buttons ---------- */

/* Tagup's bracketed corners. */
.button {
  --corner: var(--fg);
  display: inline-block;
  cursor: pointer;
  color: var(--fg);
  border: 0;
  padding: 0.6rem 1rem;
  background:
    linear-gradient(var(--corner), var(--corner)) top left / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) top left / 1.5px 8px,
    linear-gradient(var(--corner), var(--corner)) top right / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) top right / 1.5px 8px,
    linear-gradient(var(--corner), var(--corner)) bottom left / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) bottom left / 1.5px 8px,
    linear-gradient(var(--corner), var(--corner)) bottom right / 8px 1.5px,
    linear-gradient(var(--corner), var(--corner)) bottom right / 1.5px 8px,
    var(--raised);
  background-repeat: no-repeat;
}
.button:hover { background-color: var(--border); }

.link-button {
  font: inherit;
  font-size: 14px;
  color: var(--muted);
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
.link-button:hover { color: var(--fg); }

/* ---------- Aircraft panel ---------- */

.panel {
  background: var(--surface);
  padding: var(--gutter);
  display: grid;
  align-content: start;
  gap: 1.75rem;
}

.panel-close { color: var(--muted); text-decoration: none; justify-self: start; }
.panel-close:hover { color: var(--fg); }

.panel-head { display: grid; gap: 0.35rem; }
.panel-head h2 { font-family: var(--font-mono); font-size: 26px; font-weight: 500; letter-spacing: 0.02em; }
.panel-head .status { font-size: 14px; }
.panel-reason { color: var(--muted); }

.file-writeup[open] > summary { margin-bottom: 1rem; }

form { display: grid; gap: 0.9rem; }
form .button { justify-self: start; }
.form-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem; }

.field { display: grid; gap: 0.35rem; border: 0; padding: 0; margin: 0; }
.field > span, .field legend { color: var(--muted); padding: 0; margin-bottom: 0.35rem; }
.field input:not([type="radio"]), .field select { width: 100%; }
.choices { display: flex; gap: 1.25rem; }
.choices label { display: flex; align-items: center; gap: 0.4rem; cursor: pointer; }
input[type="radio"] { accent-color: var(--fg); margin: 0; }

.error {
  color: var(--grounded);
  border: 1px solid var(--grounded);
  background: var(--grounded-tint);
  padding: 0.5rem 0.75rem;
}

.open-writeups, .history { display: grid; gap: 0.75rem; }
.open-writeups h3 span { margin-left: 0.5rem; }
.open-writeups h3, .history h3 { color: var(--muted); }

/* ---------- Write-up cards: each part edits itself ---------- */

.writeup {
  border: 1px solid var(--border);
  background: var(--bg);
  padding: 0.9rem 1rem 1rem;
  display: grid;
  gap: 0.6rem;
  scroll-margin-top: 1rem;
}
.writeup.severity-high { border-color: rgb(252 165 165 / 0.45); }

.card-top { display: flex; align-items: center; gap: 0.6rem; min-height: 1.75rem; }
.corner { margin-left: auto; display: flex; align-items: center; gap: 0.5rem; }

.state {
  font-size: 11px;
  color: var(--muted);
  border: 1px solid var(--border);
  background: var(--raised);
  padding: 0.1rem 0.45rem;
}

.edit { position: relative; }

/* Severity and date look like what they are, with a dotted underline to say they can change. */
.edit-severity > summary, .edit-date > summary {
  padding: 0.15rem 0.25rem;
  margin: -0.15rem -0.25rem;
  text-decoration: underline dotted;
  text-decoration-color: var(--border);
  text-underline-offset: 0.35em;
}
.edit-severity > summary:hover, .edit-date > summary:hover,
.edit-severity[open] > summary, .edit-date[open] > summary {
  background: var(--raised);
  text-decoration-color: currentColor;
}
.edit-date > summary { color: var(--fg); font-size: 12px; }

.popover {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: 0;
  z-index: 5;
  width: min(20rem, calc(100vw - 4rem));
  background: var(--raised);
  border: 1px solid var(--border);
  padding: 1rem;
  box-shadow: 0 12px 32px rgb(0 0 0 / 0.6);
  text-transform: none;
  letter-spacing: normal;
}
.popover-end { left: auto; right: 0; }

.edit-description > summary {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  font-size: 16px;
  padding: 0.25rem 0.4rem;
  margin: -0.25rem -0.4rem;
}
.edit-description > summary::after {
  content: "Edit";
  flex: none;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: 0;
}
.edit-description > summary:hover { background: var(--raised); }
.edit-description > summary:hover::after,
.edit-description > summary:focus-visible::after { opacity: 1; }
.edit-description[open] > summary { color: var(--muted); }
.edit-description[open] > summary::after { content: "Close"; opacity: 1; }
.edit-description[open] > form { margin-top: 0.75rem; }
@media (hover: none) {
  .edit-description > summary::after { opacity: 1; }
}

.meta { color: var(--muted); font-size: 13px; }

.card-actions {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  border-top: 1px solid var(--border);
  padding-top: 0.9rem;
  margin-top: 0.15rem;
}
.edit-step { flex: 1; }
.edit-step[open] > summary { background-color: var(--border); }
.edit-step[open] > form { margin-top: 1rem; }
.edit-cancel { margin-left: auto; padding-top: 0.55rem; }
.cancel-link { color: var(--muted); font-size: 14px; text-decoration: underline; text-underline-offset: 0.2em; text-decoration-color: var(--border); }
.cancel-link:hover, .edit-cancel[open] .cancel-link { color: var(--fg); }

/* ---------- History ---------- */

.timeline { list-style: none; padding: 0; display: grid; }
.timeline li {
  display: grid;
  gap: 0.15rem;
  padding: 0.75rem 0 0.75rem 1rem;
  border-left: 1px solid var(--border);
  position: relative;
}
.timeline li::before {
  content: "";
  position: absolute;
  left: -3.5px;
  top: 1.1rem;
  width: 6px;
  height: 6px;
  background: var(--muted);
}
.when { color: var(--muted); font-size: 11px; }
.note { color: var(--fg); max-width: 60ch; }
.note::before { content: "“"; }
.note::after { content: "”"; }
.ref { color: var(--muted); font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ---------- Narrow screens ---------- */

@media (max-width: 640px) {
  .fleet thead { display: none; }
  .fleet .group-head { display: flex; justify-content: space-between; border-bottom: 1px solid currentColor; }
  .fleet .group-head > * { border: 0; }
  .fleet tr:not(.group-head) { display: grid; grid-template-columns: auto 1fr; gap: 0.25rem 0.75rem; padding: 0.75rem 0.5rem; border-bottom: 1px solid var(--border); }
  .fleet tr:not(.group-head) > * { padding: 0; border: 0; width: auto; }
  .fleet tr:not(.group-head) > .attention { grid-column: 2; }
  .fleet tr:not(.group-head) > .attention:empty { display: none; }
  .row-writeups li { grid-template-columns: 4rem minmax(0, 1fr); }
  .search input { flex: 1; width: auto; }
}

